<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/auth.php';
$pageTitle='Riwayat Transaksi';
$q=clean_text((string)($_GET['q']??''),100);
$kategori=(string)($_GET['kategori']??'Semua');
if(!in_array($kategori,['Semua','Rambut','Perawatan'],true)) $kategori='Semua';
$page=max(1,filter_var($_GET['page']??1,FILTER_VALIDATE_INT)?:1); $perPage=12; $offset=($page-1)*$perPage;
$where=[]; $params=[];
if($kategori!=='Semua') { $where[]="EXISTS (SELECT 1 FROM detail_transaksi dx LEFT JOIN layanan lx ON lx.id_layanan=dx.id_layanan WHERE dx.id_transaksi=t.id_transaksi AND COALESCE(NULLIF(dx.kategori_snapshot,''),lx.kategori)=?)"; $params[]=$kategori; }
if($q!=='') { $where[]="(t.no_transaksi LIKE ? OR t.nama_pelanggan LIKE ? OR EXISTS (SELECT 1 FROM detail_transaksi ds LEFT JOIN layanan ls ON ls.id_layanan=ds.id_layanan WHERE ds.id_transaksi=t.id_transaksi AND COALESCE(NULLIF(ds.nama_layanan_snapshot,''),ls.nama_layanan) LIKE ?))"; $like='%'.$q.'%'; array_push($params,$like,$like,$like); }
$whereSql=$where?' WHERE '.implode(' AND ',$where):'';
$countStmt=$pdo->prepare('SELECT COUNT(*) FROM transaksi t'.$whereSql); $countStmt->execute($params); $totalRows=(int)$countStmt->fetchColumn(); $totalPages=max(1,(int)ceil($totalRows/$perPage)); if($page>$totalPages){$page=$totalPages;$offset=($page-1)*$perPage;}
$sql="SELECT t.id_transaksi,t.no_transaksi,t.tanggal_transaksi,t.nama_pelanggan,t.total_biaya,COUNT(d.id_detail) jumlah_layanan,GROUP_CONCAT(DISTINCT COALESCE(NULLIF(d.nama_layanan_snapshot,''),l.nama_layanan) ORDER BY COALESCE(NULLIF(d.nama_layanan_snapshot,''),l.nama_layanan) SEPARATOR ', ') layanan,GROUP_CONCAT(DISTINCT COALESCE(NULLIF(d.kategori_snapshot,''),l.kategori) ORDER BY COALESCE(NULLIF(d.kategori_snapshot,''),l.kategori) SEPARATOR ', ') kategori_list FROM transaksi t LEFT JOIN detail_transaksi d ON d.id_transaksi=t.id_transaksi LEFT JOIN layanan l ON l.id_layanan=d.id_layanan {$whereSql} GROUP BY t.id_transaksi,t.no_transaksi,t.tanggal_transaksi,t.nama_pelanggan,t.total_biaya ORDER BY t.tanggal_transaksi DESC,t.id_transaksi DESC LIMIT {$perPage} OFFSET {$offset}";
$stmt=$pdo->prepare($sql); $stmt->execute($params); $rows=$stmt->fetchAll();
$overallStats = $pdo->query('SELECT COUNT(*) jumlah, COALESCE(SUM(total_biaya),0) total, COUNT(DISTINCT nama_pelanggan) pelanggan FROM transaksi')->fetch() ?: ['jumlah'=>0,'total'=>0,'pelanggan'=>0];
require __DIR__ . '/includes/header.php';
?>
<section class="panel filter-panel"><form method="get" class="filter-row"><div class="form-group grow"><label for="q">Cari transaksi</label><input class="input" id="q" name="q" value="<?= e($q) ?>" placeholder="Cari nomor transaksi, pelanggan, atau layanan"></div><div class="form-group filter-category"><label for="kategori">Kategori</label><select class="input" id="kategori" name="kategori"><option value="Semua" <?= $kategori==='Semua'?'selected':'' ?>>Semua kategori</option><option value="Rambut" <?= $kategori==='Rambut'?'selected':'' ?>>Rambut</option><option value="Perawatan" <?= $kategori==='Perawatan'?'selected':'' ?>>Perawatan</option></select></div><div class="filter-actions"><button class="btn btn-dark" type="submit">Cari</button><a class="btn btn-light" href="<?= BASE_URL ?>/riwayat.php">Reset</a></div></form></section>
<section class="stats-grid history-stats"><article class="stat-card"><div class="stat-head"><span>Total Pendapatan Tercatat</span><span class="stat-symbol">Rp</span></div><strong class="stat-value compact"><?= rupiah($overallStats['total']) ?></strong><small>Akumulasi seluruh transaksi</small></article><article class="stat-card"><div class="stat-head"><span>Jumlah Transaksi</span><span class="stat-symbol"><?= ui_icon('receipt') ?></span></div><strong class="stat-value"><?= (int)$overallStats['jumlah'] ?></strong><small><?= (int)$totalRows ?> sesuai pencarian saat ini</small></article><article class="stat-card"><div class="stat-head"><span>Pelanggan Terlayani</span><span class="stat-symbol"><?= ui_icon('user') ?></span></div><strong class="stat-value"><?= (int)$overallStats['pelanggan'] ?></strong><small>Pelanggan unik tercatat</small></article></section>
<section class="panel table-panel"><div class="panel-heading"><div><h2>Riwayat Transaksi &amp; Layanan</h2><p><?= $totalRows ?> transaksi ditemukan.</p></div><span class="pill">Halaman <?= $page ?> dari <?= $totalPages ?></span></div><div class="table-wrap"><table><thead><tr><th>No. Transaksi</th><th>Waktu</th><th>Pelanggan</th><th>Layanan</th><th>Kategori</th><th>Total</th><th>Aksi</th></tr></thead><tbody>
<?php if(!$rows): ?><tr><td colspan="7"><div class="empty-state">Belum ada transaksi yang sesuai. <a href="<?= BASE_URL ?>/transaksi.php">Catat transaksi baru</a>.</div></td></tr><?php else: foreach($rows as $row): ?><tr><td><strong><?= e($row['no_transaksi']) ?></strong></td><td><?= e(date('d/m/Y H:i',strtotime($row['tanggal_transaksi']))) ?></td><td><strong><?= e($row['nama_pelanggan']) ?></strong></td><td><?= e($row['layanan']?:'-') ?></td><td><span class="badge <?= strpos((string)$row['kategori_list'],'Perawatan') !== false?'badge-green':'badge-gray' ?>"><?= e($row['kategori_list']?:'-') ?></span></td><td><strong><?= rupiah($row['total_biaya']) ?></strong></td><td><a class="action-icon" title="Ubah transaksi" aria-label="Ubah transaksi" href="<?= BASE_URL ?>/transaksi_edit.php?id=<?= (int)$row['id_transaksi'] ?>"><?= ui_icon('pencil') ?></a></td></tr><?php endforeach; endif; ?>
</tbody></table></div>
<?php if($totalPages>1): ?><div class="pagination"><?php $queryBase=['q'=>$q,'kategori'=>$kategori]; if($page>1): ?><a href="?<?= e(http_build_query($queryBase+['page'=>$page-1])) ?>">← Sebelumnya</a><?php endif; ?><span><?= $page ?> / <?= $totalPages ?></span><?php if($page<$totalPages): ?><a href="?<?= e(http_build_query($queryBase+['page'=>$page+1])) ?>">Berikutnya →</a><?php endif; ?></div><?php endif; ?>
</section>
<?php require __DIR__ . '/includes/footer.php'; ?>
